class Solution:
    def numTimesAllBlue(self, light: list[int]) -> int:
        n = len(light)
        right_max = 0
        count = 0
        for i in range(n):
            right_max = max(right_max, light[i])
            if right_max == i + 1:
                count += 1
        return count

