class Solution:
    def unhappyFriends(self, n: int, preferences: List[List[int]], pairs: List[List[int]]) -> int:
        pair_dict = {}
        for x, y in pairs:
            pair_dict[x] = y
            pair_dict[y] = x

        unhappy_friends = set()

        for x in range(n):
            y = pair_dict[x]
            for u in preferences[x]:
                if u == y:
                    break
                v = pair_dict[u]
                if preferences[u].index(x) < preferences[u].index(v):
                    unhappy_friends.add(x)
                    break

        return len(unhappy_friends)
